from dateutil.relativedelta import relativedelta
from datetime import datetime, date, timedelta
import random
random.seed(1)
names=['days','hours','minutes','seconds','microseconds','weeks']
bad=[]
for i in range(30000):
    kw={}
    for n in names:
        if random.random()<0.35:
            kw[n]=round(random.uniform(-50,50),4)
    try:
        rd=relativedelta(**kw)
        td=timedelta(**kw)
    except Exception as e:
        continue
    d=datetime(2000,3,1,12,30,45,123456)
    if d+rd != d+td:
        bad.append(('add',kw,d+rd,d+td))
    if rd+d != td+d:
        bad.append(('radd',kw,rd+d,td+d))
    if d-rd != d-td:
        bad.append(('rsub',kw,d-rd,d-td))
    if -rd != -td:
        bad.append(('neg',kw,repr(-rd),repr(-td)))
    # normalized vs timedelta
    if (d + rd.normalized()) != (d+td):
        bad.append(('norm',kw,d+rd.normalized(),d+td))
    f=round(random.uniform(-3,3),3)
    if d + rd*f != d + td*f:
        bad.append(('mul',kw,f,d+rd*f,d+td*f))
    if d + rd/f != d + td/f:
        bad.append(('div',kw,f,d+rd/f,d+td/f))
print(len(bad))
for b in bad[:15]: print(b)
